// Rules 'activityNewestFirst', 'executionNeverEdited' come from the entity list but do not apply to this write (they govern a read or another operation of the entity): no AppError carries them here (hand adjustment, see how/docs/correcoes_a_mao.md).
import { AppError } from '/_102034_/l1/server/layer_2_controllers/contracts.js';
import type { RequestContext } from '/_102034_/l1/server/layer_2_controllers/contracts.js';
import { resolveRepository } from '/_102034_/l1/server/layer_2_application/repositoryRegistry.js';
import type { ExecutionSummary } from '/_102047_/l1/agents/layer_3_domain/entities/executionSummary.js';
import type { ExecutionSummaryRepository } from '/_102047_/l1/agents/layer_2_application/ports/executionSummaryRepository.js';

export interface CreateExecutionSummaryInput extends Record<string, unknown> {
  agentId: string;
  personId?: string;
  executionRef: string;
  startedAt: string;
  details: {
    durationMs: number;
    cost?: string;
    tookOver: boolean;
    conversationLink?: string;
    actions: {
      toolName: string;
      result: string;
      resultNote?: string;
    }[];
  };
}

export interface CreateExecutionSummaryOutput extends Record<string, unknown> {
  id: string;
  version: number;
  agentId: string;
  personId?: string;
  executionRef: string;
  startedAt: string;
  details: {
    durationMs: number;
    cost?: string;
    tookOver: boolean;
    conversationLink?: string;
    actions: {
      toolName: string;
      result: string;
      resultNote?: string;
    }[];
  };
}

export async function createExecutionSummary(input: CreateExecutionSummaryInput, ctx: RequestContext): Promise<CreateExecutionSummaryOutput> {
  // onlyInboundWritesExecution: only a call that arrives from the cm through a connection may record an execution.
  if (ctx.requestMeta?.source !== 'message' || !ctx.requestMeta.connection) {
    throw new AppError('INBOUND_ONLY', 'Execution summaries are recorded only from what the cm sends.', 403, { ruleId: 'onlyInboundWritesExecution' });
  }

  const filled = (value: unknown): boolean => value !== undefined && value !== null && value !== '';

  if (!filled(input.agentId)) throw new AppError('INVALID_INPUT', 'agentId is required.', 400);
  if (!filled(input.executionRef)) throw new AppError('INVALID_INPUT', 'executionRef is required.', 400, { ruleId: 'executionRecordedOnce' });
  const executionRef = String(input.executionRef);
  if (executionRef.length > 120) throw new AppError('INVALID_INPUT', 'executionRef is longer than 120 characters.', 400);
  if (!filled(input.startedAt)) throw new AppError('INVALID_INPUT', 'startedAt is required.', 400);
  const startedAt = String(input.startedAt);
  if (Number.isNaN(Date.parse(startedAt))) {
    throw new AppError('INVALID_INPUT', 'startedAt is not a valid timestamp.', 400);
  }

  const details = input.details;
  if (!details || typeof details !== 'object') throw new AppError('INVALID_INPUT', 'details is required.', 400);
  const durationMs = Number(details.durationMs);
  if (!Number.isInteger(durationMs) || durationMs < 0) {
    throw new AppError('INVALID_INPUT', 'durationMs must be a non-negative integer.', 400);
  }
  if (typeof details.tookOver !== 'boolean') throw new AppError('INVALID_INPUT', 'tookOver is required.', 400);
  if (!Array.isArray(details.actions)) throw new AppError('INVALID_INPUT', 'actions must be a list.', 400);

  const allowedResults = ['succeeded', 'failed', 'refused'] as const;
  const actions: ExecutionSummary['details']['actions'] = details.actions.map((action) => {
    if (!action || !filled(action.toolName)) throw new AppError('INVALID_INPUT', 'Each action needs a toolName.', 400);
    const toolName = String(action.toolName);
    if (toolName.length > 200) throw new AppError('INVALID_INPUT', 'toolName is longer than 200 characters.', 400);
    const result = allowedResults.find((value) => value === action.result);
    if (!result) throw new AppError('INVALID_INPUT', 'Each action result must be succeeded, failed or refused.', 400);
    const built: ExecutionSummary['details']['actions'][number] = { toolName, result };
    if (filled(action.resultNote)) {
      const note = String(action.resultNote);
      if (note.length > 1000) throw new AppError('INVALID_INPUT', 'resultNote is longer than 1000 characters.', 400);
      built.resultNote = note;
    }
    return built;
  });

  const builtDetails: ExecutionSummary['details'] = { durationMs, tookOver: details.tookOver, actions };
  if (filled(details.cost)) builtDetails.cost = String(details.cost);
  if (filled(details.conversationLink)) {
    const link = String(details.conversationLink);
    if (link.length > 500) throw new AppError('INVALID_INPUT', 'conversationLink is longer than 500 characters.', 400);
    builtDetails.conversationLink = link;
  }

  const repository = resolveRepository<ExecutionSummaryRepository>(ctx, 'ExecutionSummaryRepository');

  // executionRecordedOnce: the same execution reference is never recorded twice.
  const existing = await repository.list({ executionRef });
  if (existing.length > 0) {
    throw new AppError('EXECUTION_ALREADY_RECORDED', 'This execution was already recorded.', 409, { ruleId: 'executionRecordedOnce' });
  }

  const record: ExecutionSummary = {
    id: ctx.idGenerator.newId(),
    version: 1,
    agentId: String(input.agentId),
    executionRef,
    startedAt,
    details: builtDetails,
  };
  if (filled(input.personId)) record.personId = String(input.personId);

  const saved = await repository.create(record);

  const output: CreateExecutionSummaryOutput = {
    id: saved.id,
    version: saved.version,
    agentId: saved.agentId,
    executionRef: saved.executionRef,
    startedAt: saved.startedAt,
    details: {
      durationMs: saved.details.durationMs,
      tookOver: saved.details.tookOver,
      actions: saved.details.actions.map((action) => {
        const out: { toolName: string; result: string; resultNote?: string } = { toolName: action.toolName, result: action.result };
        if (action.resultNote !== undefined) out.resultNote = action.resultNote;
        return out;
      }),
    },
  };
  if (saved.personId !== undefined) output.personId = saved.personId;
  if (saved.details.cost !== undefined) output.details.cost = saved.details.cost;
  if (saved.details.conversationLink !== undefined) output.details.conversationLink = saved.details.conversationLink;
  return output;
}

